"""Small real image payloads used by upload tests."""

from __future__ import annotations

import base64

PNG_1X1 = base64.b64decode(
    "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNk+A8AAQUBAScY42YAAAAASUVORK5CYII="
)

JPEG_2X2 = base64.b64decode(
    ""
)

WEBP_1X1 = base64.b64decode(
    "UklGRiQAAABXRUJQVlA4IBgAAAAwAQCdASoBAAEAAUAmJaQAA3AA/vuUAAA="
)


def image_file(filename: str, content: bytes) -> tuple[str, tuple[str, bytes, str]]:
    media_type = {
        ".png": "image/png",
        ".jpg": "image/jpeg",
        ".jpeg": "image/jpeg",
        ".webp": "image/webp",
    }[filename[filename.rfind(".") :].lower()]
    return filename, (filename, content, media_type)
